mapper.select:
SELECT TEMP.*, bbd.BOOKSET_DATE AS booksetDate FROM ( SELECT bc.BOOKSET_ID AS booksetId, bc.BOK_DETAIL_ID as bokDetailId,
nvl(bdi.BUSI_ID,ddeal.finprod_id) as busiId,
nvl(bdi.BUSI_DETAIL_TYPE,ddeal.finprod_type) as busiDetailType, bc.TABLE_ID AS tableId, bc.SUBJECT_NO AS subjectNo,
nvl(bdi.INV_AIM,decode(bc.table_id,'1413',ddeal.inv_aim,null)) as invAim, bc.O_CCY AS oCcy, bc.B_CCY AS bCcy, bc.BAL_FLAG_HAPPEN_DATE as balFlagHappenDate, bc.O_AMT_HAPPEN_DATE AS balance, bc.B_AMT_HAPPEN_DATE AS bAmt, bc.NUM_AMT_HAPPEN_DATE AS num, bc.SHARE_AMT_CLEAN AS shareAmtClean, ROW_NUMBER() OVER(PARTITION BY bc.BOOKSET_ID, bc.BOK_DETAIL_ID, /**bc.BASE_SUBJECT_NATURE,**/ bc.SUBJECT_NO, bc.BRANCH, bc.O_CCY ORDER BY bc.BOOK_ORDER DESC ) AS rn, bc.HAPPEN_DATE AS happenDate, bc.BASE_SUBJECT_NATURE as baseSubjectNature,
bc.DETAIL_SUBJECT_NO AS detailSubjectNo, bs.BAL_FLAG, bc.MDATE mdate, bc.BRANCH, bc.task_pri taskPri, bc.OFFSET_DATE offsetDate, bc.BOOK_DATE bookDate, bc.BOOK_ORDER bookOrder, bt.task_pri btTaskPri, bs.SUBJECT_TYPE subjectType FROM BOK_BOOKDETAIL_CURRENT bc LEFT JOIN BOK_DETAIL_ID bdi ON bdi.BOOKSET_ID = bc.BOOKSET_ID AND bdi.BOK_DETAIL_ID = bc.BOK_DETAIL_ID left join trd_product_deal ddeal on bc.trade_id = ddeal.trade_id and bc.table_id='1413' /*针对债券买断式逆回购，若BOK_DETAIL_ID表中无数据，直接取trd_product_deal交易表数据*/
LEFT JOIN SYS_BATCH_TASK bt on bt.task_id = bc.task_id LEFT JOIN BOK_BOOKSET bb ON bc.BOOKSET_ID = bb.BOOKSET_ID /**账套表**/ LEFT JOIN BOK_SUBJECT bs ON bs.BOOKSET_ID = bb.BOOKSET_ID_TMPL AND bs.SUBJECT_NO = bc.SUBJECT_NO WHERE 1=1
AND bc.BOOKSET_ID = #{booksetId}
AND bdi.BUSI_ID = #{busiId}
AND bc.HAPPEN_DATE <= #{happenDate}
AND ( bc.HAPPEN_DATE < #{happenDate} OR ( bc.HAPPEN_DATE = #{happenDate} AND nvl(bt.task_pri,bc.TASK_PRI) < #{taskPri} ) )
AND bc.BOOK_DATE <= #{bookDate} AND (bc.OFFSET_DATE < #{bookDate} OR bc.OFFSET_DATE IS NULL)
AND bdi.INV_AIM IN
#{invAim}
AND bc.BASE_SUBJECT_NATURE IN
#{baseSubjectNature}
AND bc.TABLE_ID = #{tableId}
AND bs.SUBJECT_TYPE IN
#{subjectType}
AND bc.BOK_DETAIL_ID in
#{item}
AND bc.BOK_DETAIL_ID = #{bokDetailId}
AND bc.BOOK_ORDER <= #{bookOrder}
AND ( bc.ONWAY_DATE <= #{onwayDate} OR bc.ONWAY_DATE IS NULL )
AND bc.BRANCH = #{branch}
AND bc.SUBJECT_NO = #{subjectNo}
) TEMP INNER JOIN BOK_BOOKSET_DATE bbd ON bbd.BOOKSET_ID = TEMP.booksetId WHERE TEMP.rn=1

SELECT temp.*, bbd.BOOKSET_DATE AS booksetDate FROM ( SELECT ba.BOOKSET_ID AS booksetId, ba.BOK_DETAIL_ID as bokDetailId, ba.TABLE_ID AS tableId, ba.BASE_SUBJECT_NATURE as baseSubjectNature, ba.O_CCY AS oCcy, ba.O_AMT_HAPPEN_DATE as oAmtHappenDate, ba.B_AMT_BOOK_DATE as bAmtHappenDate, ba.NUM_AMT_HAPPEN_DATE as numAmtHappenDate, ba.BAL_FLAG_HAPPEN_DATE as balFlagHappenDate, ba.O_AMT_BOOK_DATE as oAmtBookDate, ba.B_AMT_BOOK_DATE as bAmtBookDate, ba.NUM_AMT_BOOK_DATE as numAmtBookDate, ba.BAL_FLAG_BOOK_DATE as balFlagBookDate, ROW_NUMBER() OVER(PARTITION BY ba.BOOKSET_ID, ba.BOK_DETAIL_ID, /**ba.BASE_SUBJECT_NATURE,**/ ba.SUBJECT_NO, ba.BRANCH, ba.O_CCY ORDER BY ba.BOOK_ORDER DESC ) AS rn, ba.BOOK_DATE AS bookDate FROM BOK_BOOKDETAIL_ALL ba WHERE 1=1
AND ba.BOOKSET_ID = #{booksetId}
AND ba.HAPPEN_DATE < #{happenDate}
AND ba.BOOK_DATE < #{bookDate}
AND ba.BASE_SUBJECT_NATURE IN
#{baseSubjectNature}
AND ba.BOK_DETAIL_ID = #{bokDetailId}
AND ba.SUBJECT_NO = #{subjectNo}
) TEMP INNER JOIN BOK_BOOKSET_DATE bbd ON bbd.BOOKSET_ID = TEMP.BOOKSETID WHERE TEMP.rn=1

SELECT BASE_SUBJECT_NATURE
FROM BOK_SUBJECT_NATURE_GROUP
WHERE GROUP_ID = #{groupId}
 AND ACCT_STANDARD_ID = #{acctStandardId}

select sum(detail.O_HAPPEN_AMT)
from TRD_VOUCH_DEAL deal
		 left join TRD_VOUCH_DEAL_DETAIL detail on deal.TRADE_ID = detail.TRADE_ID
where deal.BOOKSET_ID = #{booksetId}
and detail.CD_FLAG = #{cdFlag}
and deal.BOOK_DATE = #{bookDate}
group by deal.BOOKSET_ID,deal.BOOK_DATE,detail.CD_FLAG

SELECT * FROM( SELECT a.BOOKSET_ID AS booksetId, /**账套代码**/ a.HAPPEN_DATE AS happenDate, /**发生日期**/ a.BOOK_DATE AS bookDate, /**入账日期**/ a.BOOKSET_DATE AS booksetDate, /**账套日期**/ a.PROFIT_TYPE AS profitType, /**收益类型**/ a.CAPITAL AS capital, /**实收资本**/ a.NET_ASSET_VALUE_BEF AS netAssetValueBef, /**费前资产净值**/ a.NET_ASSET_VALUE AS netAssetValue, /**资产净值**/ a.NET_UNIT_VALUE_BEF AS netUnitValueBef, /**费前单位净值**/ a.NET_UNIT_VALUE AS netUnitValue, /**单位净值**/ a.P_YIELD_BEF AS pYieldBef, /**万份收益_费前**/ a.P_YIELD AS pYield, /**万份收益**/ a.TDY_YIELD_BEF AS tdyYieldBef, /**当日年化收益率_费前**/ a.TDY_YIELD AS tdyYield, /**当日年化收益率**/ a.YIELD_TERM_BEF AS yieldTermBef, /**周期年化收益率_费前**/ a.YIELD_TERM AS yieldTerm, /**周期年化收益率**/ a.YIELD_7_BEF AS yield7Bef, /**当日7日年化收益率_费前**/ a.YIELD_7 AS yield7, /**当日7日年化收益率**/ a.TOT_BOUNS_AMT AS totBounsAmt, /**累计分红金额**/ a.TDY_BOUNS_AMT AS tdyBounsAmt, /**当日分红金额**/ a.TOT_BOUNS_NET AS totBounsNet, /**累计分红净值**/ a.TDY_BOUNS_NET AS tdyBounsNet, /**当日分红净值**/ a.PROFIT_AMT AS profitAmt, /**应付利润**/ a.TOT_PROFIT_AMT AS totProfitAmt, /**累计应付利润**/ a.INT_RATE AS intRate, /**计提利率（当日发生）**/
a.layering_id,/**分层代码**/
ROW_NUMBER() OVER(PARTITION BY BOOKSET_ID, HAPPEN_DATE ORDER BY BOOKSET_DATE DESC) AS rn FROM BOK_STAT_BOK_POSITION a WHERE 1 = 1
AND a.HAPPEN_DATE <= #{sdateEnd}
AND a.HAPPEN_DATE >= #{sdateStart}
AND a.HAPPEN_DATE IN
#{item}
AND a.BOOKSET_ID = #{booksetId}
AND a.BOOK_DATE <= #{bookDate}
AND a.FINPROD_ID = #{finprodId}
AND a.layering_Id = #{layeringId}
AND a.is_sub_prd = #{isSubPrd}
AND EXISTS ( SELECT * FROM BOK_ACCT_LAYERING_INFO b WHERE b.bookset_id = a.bookset_id AND b.layering_id = a.layering_id AND b.bok_detail_id = #{bokDetailId} )
) WHERE rn = 1

WITH TMP AS( SELECT B.BOOKSET_ID,/**账套 -账套代码**/ B.ACCT_SUBJECT_ID,/**账套-核算主体代码**/ B.STANDARD_CCY,/**账套-本位币**/ H.BOOKSET_DATE,/**账套日期**/ H.BOOK_DATE/**入账日期**/ FROM BOK_BOOKSET B/**账套表**/ INNER JOIN BOK_BATCH_TASK_TODO H/**批处理待处理任务表**/ ON B.BOOKSET_ID=H.BOOKSET_ID AND B.ACCT_SUBJECT_TYPE = #{accSubjectType} where 1=1 AND H.SEQ_NO = #{seqNo} AND H.BOOKSET_DATE = #{BOOKSET_DATE} AND H.BOOK_DATE = #{BOOK_DATE} AND H.HAPPEN_DATE = #{HAPPEN_DATE} AND H.TASK_ID = #{taskId} ) SELECT E.FINPROD_ID, /**金融产品代码**/ E.FINPROD_TYPE, /**金融产品类型**/ E.VDATE, /**起息日**/ E.TRADE_MARKET, /** 交易场所 **/ E.CALENDAR_ID, /** 交易日历 **/ E.ACTMDATE, /** 实际到期日 **/ F.CASH_ID, /**现金流代码**/ F.CASH_TYPE_1, /**现金流一级类型**/ F.CASH_TYPE_2, /**现金流二级类型**/ G.BOOKSET_ID, /**账套代码**/ G.BOOKSET_DATE, /**账套日期**/ G.BOOK_DATE, /**入账日期**/ G.STANDARD_CCY, /**本位币**/ VBD.BOK_DETAIL_ID /**账务明细代码**/ FROM TMP G left JOIN FIN_PRODUCT E ON E.FINPROD_ID = G.ACCT_SUBJECT_ID INNER JOIN FIN_CASH_INFO F ON g.ACCT_SUBJECT_ID = F.FINPROD_ID
AND F.CASH_TYPE_2 IN
#{cashType}
INNER JOIN BOK_DETAIL_ID VBD ON F.FINPROD_ID = VBD.BUSI_ID
and VBD.BOOKSET_ID=g.BOOKSET_ID
WHERE E.VDATE<=#{HAPPEN_DATE} AND E.ACTMDATE>=#{HAPPEN_DATE}
AND E.PROFIT_TYPE = #{profitType}

 	SELECT 																		
