SELECT C.SUBJECT_NO, C.BASE_SUBJECT_NATURE FROM BOK_BUSS_DETSUB a INNER JOIN BOK_BOOKSET b ON B.BOOKSET_ID = A.BOOKSET_ID INNER JOIN BOK_SUBJECT C ON C.BOOKSET_ID = B.BOOKSET_ID_TMPL AND A.FSUBJECT_ID = C.SUBJECT_NO WHERE A.BOOKSET_ID = #{booksetId} AND A.DETAIL_SUBJECT_NO_TAIL = #{detailSubjectNoTail} AND C.BASE_SUBJECT_NATURE IN (
#{item}
)

