		      SELECT 
		        A.*,
		        ROW_NUMBER() OVER(PARTITION BY BOOKSET_ID,BOK_DETAIL_ID,HAPPEN_DATE ORDER BY BOOK_SUMMARY_ORDER DESC) AS rn
