WITH TMP AS (SELECT B.BOOKSET_ID BOOKSET_ID, /** 账套代码**/ B.STANDARD_CCY STANDARD_CCY, /** 本位币**/ B.ACCT_MODE ACCT_MODE, /** 核算方式 add by dongjun on 20190220**/ f.vdate, /**起息日**/ f.mdate, /**到期日**/ f.layering_id layeringId, /**分层代码**/ f.busi_id finprod_Id, /**金融产品代码**/ f.busi_detail_type finprod_Type, /**金融产品类型**/ f.calendar_id calendar_Id, /**交易日历**/ f.branch, /**分支序号**/ H.BOOKSET_DATE BOOKSET_DATE, /** 账套日期**/ H.BOOK_DATE BOOK_DATE, /** 入账日期**/ f.lev lev /**级别序号**/ FROM BOK_BOOKSET B INNER JOIN BOK_BATCH_TASK_TODO H ON B.BOOKSET_ID = H.BOOKSET_ID INNER JOIN BOK_ACCT_LAYERING_INFO f on b.bookset_id = f.bookset_id WHERE 1=1
AND B.acct_mode = #{profitType}
and (f.vdate <= #{cdate} or f.vdate is null) and (f.mdate >= #{cdate} or f.mdate is null) and h.seq_no = #{seqNo,jdbcType=VARCHAR} and h.bookset_date =#{BOOKSET_DATE,jdbcType=DATE} and h.book_date =#{BOOK_DATE,jdbcType=DATE} and h.happen_date =#{HAPPEN_DATE,jdbcType=DATE} and h.task_id = #{taskId,jdbcType=VARCHAR} AND H.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET} ) SELECT tmp.finprod_Id finprodId, /** 金融产品代码 **/ tmp.finprod_Type finprodType, /** 金融产品类型 **/ tmp.VDATE, /** 起息日**/ tmp.mdate actmdate, /** 实际到期日 **/ tmp.calendar_Id calendarId, /** 交易日历 **/ tmp.branch,/**分支序号**/ tmp.ACCT_MODE acctMode,/** 核算方式 add by dongjun on 20190220**/ C.CASH_ID cashId, /** 现金流代码 **/ C.CASH_TYPE_1 cashType1, /** 现金流一级类型 **/ C.CASH_TYPE_2 cashType2, /** 现金流二级类型 **/ tmp.BOOKSET_ID booksetId, /** 帐套代码 **/ tmp.BOOKSET_DATE booksetDate, /** 帐套日期 **/ tmp.BOOK_DATE bookDate, /** 入账日期 **/ tmp.STANDARD_CCY standardCcy, /** 本位币 **/ tmp.lev,/**级别序号**/ tmp.layeringId, /** 2018年12月7日魏鹏：分层代码 **/ BOK.BOK_DETAIL_ID bokDetailId /** 账务明细代码 **/ from TMP INNER JOIN FIN_CASH_INFO C ON tmp.FINPROD_ID = C.FINPROD_ID and tmp.branch = c.branch
AND c.CASH_TYPE_2 IN
#{item}
and (c.IS_CALC = #{isCalc,jdbcType=VARCHAR} or c.IS_CALC is null) INNER JOIN BOK_DETAIL_ID BOK ON tmp.FINPROD_ID = BOK.BUSI_ID AND tmp.FINPROD_TYPE = BOK.BUSI_DETAIL_TYPE and tmp.BOOKSET_ID = BOK.BOOKSET_ID and tmp.branch = BOK.branch

SELECT count(1) FROM ( SELECT cur.OFFSET_FLAG, row_number() over (PARTITION BY cur.BOOKSET_ID, cur.BOOK_ID ORDER BY cur.BOOK_ORDER desc) as rn FROM BOK_BOOKDETAIL_CURRENT cur WHERE cur.BOOKSET_ID = #{booksetId} AND cur.BOOK_DATE <= #{bookDate} AND cur.TABLE_ID = #{tableId}
AND ((cur.HAPPEN_DATE = #{happenDate} AND cur.ONWAY_DATE is NULL) OR cur.ONWAY_DATE = #{happenDate})
AND cur.BASE_SUBJECT_NATURE IN
#{baseSubjectNature}
AND cur.BOK_DETAIL_ID = #{bokDetailId}
) a WHERE rn=1 AND OFFSET_FLAG = #{offsetFlag}

WITH voucher AS ( SELECT TEMP.happenDate, /**发生日期**/ TEMP.booksetDate, /**账套日期**/ TEMP.bookDate, /**入账日期**/ TEMP.bookId, /**凭证编号**/ TEMP.booksetId /**账套代码**/ FROM ( SELECT cur.HAPPEN_DATE as happenDate, /**发生日期**/ cur.BOOKSET_DATE as booksetDate, /**账套日期**/ cur.BOOK_DATE as bookDate,/**入账日期**/ cur.BOOK_ID as bookId,/**凭证编号**/ cur.BOOKSET_ID as booksetId, /**账套代码**/ cur.OFFSET_FLAG as offsetFlag, /**冲正标识**/ ROW_NUMBER() OVER(PARTITION BY cur.BOOKSET_ID, cur.BOOK_ID ORDER BY cur.BOOK_ORDER desc) as rn FROM BOK_BOOKDETAIL_CURRENT cur WHERE 1=1 AND cur.BOOKSET_ID = #{booksetId} /**账套代码**/ AND cur.BOOK_DATE <= #{bookDate} /**入账日**/
/**场景代码**/ AND cur.TABLE_ID IN
#{tableId}
AND cur.TRADE_ID = #{tradeId} /**交易编号**/ AND cur.HAPPEN_DATE <= #{happenDate} /**发生日**/ AND cur.HAPPEN_DATE >= #{beginHappenCycDate} AND cur.HAPPEN_DATE <= #{endHappenCycDate} ) TEMP WHERE TEMP.rn = 1 AND TEMP.offsetFlag = #{offsetFlag} /**冲正标识**/ )
SELECT crt.*/**账务明细表（当前表）.全部项目**/ FROM BOK_BOOKDETAIL_CURRENT crt INNER JOIN voucher vr on crt.happen_date = vr.happenDate and crt.BOOKSET_DATE = vr.booksetDate and crt.BOOK_DATE = vr.bookDate and crt.BOOK_ID = vr.bookId WHERE 1 =1
/**科目性质**/ AND crt.BASE_SUBJECT_NATURE IN
#{baseSubjectNature}
AND crt.BOK_DETAIL_ID = #{bokDetailId} /**账务明细代码**/
AND ( crt.HAPPEN_DATE <= #{onwayDate} AND crt.ONWAY_DATE > #{onwayDate})
AND crt.MDATE is not null ORDER BY crt.MDATE DESC

    	SELECT 																											
			A.FINPROD_ID finprodId,	/** 金融产品代码 **/																										
			A.FINPROD_TYPE finprodType,/** 金融产品类型	**/	 																									
			A.VDATE vdate,	/** 起息日**/	 																										
			A.TRADE_MARKET tradeMarket,	/** 交易场所 **/	 																										
			A.CALENDAR_ID calendarId,	/** 交易日历 **/	


			 		A.ACTMDATE actmdate,	/** 实际到期日 **/	


			 		 A.mdate actmdate,	/** 实际到期日 **/	



			C.CASH_ID cashId,	/** 现金流代码 **/	 
			C.CASH_TYPE_1 cashType1,	/** 现金流一级类型 **/																								
			C.CASH_TYPE_2 cashType2,	/** 现金流二级类型 **/	 																										
			BOK.BOK_DETAIL_ID bokDetailId,	/** 账务明细代码 **/	
			bok.bookset_id booksetId /**账套代码 **/																																																			
		FROM	


		 		FIN_PRODUCT A	


		 		fin_trade_product A		


		INNER JOIN FIN_CASH_INFO C																	
		ON A.FINPROD_ID = C.FINPROD_ID		

	    	AND CASH_TYPE_2 IN

	                #{item}


		INNER JOIN BOK_DETAIL_ID BOK																																														
			ON	C.FINPROD_ID = BOK.BUSI_ID

				and BOK.bookset_Id=#{booksetId}




 						and BOK.branch=#{branch}


						and BOK.busi_Detail_Type=#{busiDetailType}



		WHERE 1=1

			and A.VDATE <= #{cdate}		


			 		AND A.ACTMDATE >= #{cdate}


