				AND A.PROFIT_TYPE = #{profitType}


				AND A.finprod_Id = #{finprodId}


				and a.FINPROD_type=#{busiDetailType}




 						and a.branch=#{branch}

SELECT * from BOK_ACCT_LAYERING_INFO i where 1=1
and i.bookset_Id=#{booksetId}
and (i.lev like #{lev}||'-%' or i.lev = #{lev})

WITH TMP AS (SELECT B.BOOKSET_ID BOOKSET_ID, /** 账套代码**/ b.acct_subject_id FINPROD_ID,/*核算主体代码 */ b.acct_subject_type FINPROD_TYPE,/*核算主体类别*/ B.STANDARD_CCY STANDARD_CCY, /** 本位币**/ b.start_date, /**账套开始日 **/ b.end_date, /**账套结束日 **/ H.BOOKSET_DATE BOOKSET_DATE, /** 账套日期**/ H.BOOK_DATE BOOK_DATE /** 入账日期**/ FROM BOK_BOOKSET B INNER JOIN BOK_BATCH_TASK_TODO H ON B.BOOKSET_ID = H.BOOKSET_ID WHERE 1=1
AND B.acct_mode = #{profitType,jdbcType=VARCHAR}
and (b.start_date <= #{cdate} or b.start_date is null) and (b.end_date >= #{cdate} or b.end_date is null) and h.seq_no = #{seqNo,jdbcType=VARCHAR} and h.bookset_date =#{BOOKSET_DATE,jdbcType=DATE} and h.book_date =#{BOOK_DATE,jdbcType=DATE} and h.happen_date =#{HAPPEN_DATE,jdbcType=DATE} and h.task_id = #{taskId,jdbcType=VARCHAR} AND H.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET} ) SELECT tmp.FINPROD_ID finprodId, /** 金融产品代码 **/ tmp.FINPROD_TYPE finprodType, /** 金融产品类型 **/ tmp.start_date VDATE, /** 起息日**/ tmp.end_date ctmdate, /** 实际到期日 **/ C.CASH_ID cashId, /** 现金流代码 **/ C.CASH_TYPE_1 cashType1, /** 现金流一级类型 **/ C.CASH_TYPE_2 cashType2, /** 现金流二级类型 **/ tmp.BOOKSET_ID booksetId, /** 帐套代码 **/ tmp.BOOKSET_DATE booksetDate, /** 帐套日期 **/ tmp.BOOK_DATE bookDate, /** 入账日期 **/ tmp.STANDARD_CCY standardCcy, /** 本位币 **/ BOK.BOK_DETAIL_ID bokDetailId /** 账务明细代码 **/ from TMP INNER JOIN FIN_CASH_INFO C ON tmp.FINPROD_ID = C.FINPROD_ID
AND c.CASH_TYPE_2 IN
#{item}
INNER JOIN BOK_DETAIL_ID BOK ON tmp.FINPROD_ID = BOK.BUSI_ID AND tmp.FINPROD_TYPE = BOK.BUSI_DETAIL_TYPE and tmp.BOOKSET_ID = BOK.BOOKSET_ID

SELECT 
	* 
FROM(
      SELECT 
          A.*,
          ROW_NUMBER() OVER(PARTITION BY A.BOOKSET_ID,A.BOK_DETAIL_ID ORDER BY A.BOOK_SUMMARY_ORDER DESC,A.ACCR_DATE DESC) AS RN
      FROM BOK_BOOKDETAIL_CURRENT_EXT A
      WHERE 1=1
       AND A.ACCR_DATE <= #{searchDate,jdbcType=DATE} 
      AND A.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
       AND A.BOK_DETAIL_ID = #{bokdetailId,jdbcType=VARCHAR} 
      AND A.BOOK_DATE <= #{bookDate,jdbcType=DATE}
) WHERE RN = 1

