SELECT
crt.*
FROM BOK_BOOKDETAIL_CURRENT crt
WHERE 1 =1
 AND crt.bookset_id = #{booksetId}  
 AND crt.TABLE_ID = #{tableId}  
 AND crt.book_date > #{beginHappenCycDate} 

	/**科目性质**/
	AND crt.BASE_SUBJECT_NATURE =#{baseSubjectNature}


	AND crt.BOK_DETAIL_ID = #{bokDetailId}	/**账务明细代码**/


	AND  crt.book_date <= #{bookDate}

ORDER BY crt.HAPPEN_DATE ASC

